"""Young-age (grades 4-6) companion activities for the upcoming weekly portions Vayetze -> Yitro (verses verbatim from Sefaria)."""
import json, re
from mk import mk
from content_tools import add_activities

SEF = 'https://www.sefaria.org.il/'
V = json.load(open('parsha_verses.json', encoding='utf8'))


def vs(k):
    s = V[k]
    s = re.sub(r'&\w+;|\{ס\}|ׄ', ' ', s)
    s = s.replace('יְהֹוָה', 'ה׳').replace('͏', '')
    s = re.sub(r'\s+', ' ', s).strip()
    return s


